def count_special_numbers(n, k):
    def count_set_bits(x):
        return bin(x).count('1')

    def bfs():
        from collections import deque
        queue = deque([(int(n, 2), 0)])
        visited = set()
        visited.add(int(n, 2))
        count = 0

        while queue:
            current, steps = queue.popleft()

            if steps == k and current == 1:
                count += 1
                count %= MOD
                continue

            if steps > k:
                continue

            for i in range(current.bit_length()):
                if current & (1 << i):
                    next_num = current - (1 << i)
                    if next_num not in visited:
                        visited.add(next_num)
                        queue.append((next_num, steps + 1))

        return count

    return bfs()

